import{_ as s,o as t,c as e,a4 as n}from"./chunks/framework.BRzJ4ijD.js";const d=JSON.parse('{"title":"第三部分 · 计算机网络","description":"","frontmatter":{},"headers":[],"relativePath":"networking/index.md","filePath":"networking/README.md","lastUpdated":1788475713000}'),o={name:"networking/index.md"};function i(l,a,p,c,r,m){return t(),e("div",null,[...a[0]||(a[0]=[n(`<h1 id="第三部分-·-计算机网络" tabindex="-1">第三部分 · 计算机网络 <a class="header-anchor" href="#第三部分-·-计算机网络" aria-label="Permalink to &quot;第三部分 · 计算机网络&quot;">​</a></h1><h2 id="一句话" tabindex="-1">一句话 <a class="header-anchor" href="#一句话" aria-label="Permalink to &quot;一句话&quot;">​</a></h2><p><code>axios.get(&#39;https://api.example.com&#39;)</code> 背后：电信号从 100BASE-T 网口出去，跨交换机、路由器、光纤骨干、CDN、TLS、负载均衡，跑几千公里到服务器再原路返回一个 JSON。这条通路上每一跳都对应一层&quot;协议&quot;负责把上一层数据装进下一层信封。读完这一部分，你应该能从字节看到光子、从 RPC 看到内核中断、从握手 RTT 看到激光相位——这就是网络工程师的全栈视角。</p><h2 id="为什么协议要分层" tabindex="-1">为什么协议要分层 <a class="header-anchor" href="#为什么协议要分层" aria-label="Permalink to &quot;为什么协议要分层&quot;">​</a></h2><p>把 5000 种硬件介质和 5000 种应用协议两两对接是 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>O</mi><mo stretchy="false">(</mo><msup><mi>n</mi><mn>2</mn></msup><mo stretchy="false">)</mo></mrow><annotation encoding="application/x-tex">O(n^2)</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:1.0641em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">O</span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal">n</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="katex-sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span> 工程，分层让接口收敛到 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>O</mi><mo stretchy="false">(</mo><mi>n</mi><mo stretchy="false">)</mo></mrow><annotation encoding="application/x-tex">O(n)</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">O</span><span class="mopen">(</span><span class="mord mathnormal">n</span><span class="mclose">)</span></span></span></span>：上层只对&quot;下一层提供的接口&quot;负责，下层只对&quot;上一层调用我的方式&quot;负责。这就是 ISO/OSI 七层真正的现实版（虽然 OSI 自己部署不出去，TCP/IP 五层活了下来）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>应用层    | HTTP/2/gRPC/MQTT     | 你写的 axios</span></span>
<span class="line"><span>传输层    | TCP/UDP/QUIC          | 内核 + 协议栈</span></span>
<span class="line"><span>网络层    | IPv4/IPv6/ICMP        | 路由表 + LPM 查找</span></span>
<span class="line"><span>数据链路层| Ethernet/WiFi/PPP     | MAC + 帧组装 + FCS</span></span>
<span class="line"><span>物理层    | 1000BASE-T/100G-QSFP  | PHY PHY PCS PMA PMD</span></span></code></pre></div><p>每一层有自己的命名空间（端口号 vs IP 地址 vs MAC 地址），自己的拥塞模型（TCP Cubic vs RED/ECN 信号 vs CSMA/CD 冲突），自己的恢复机制（重传 vs ARP 重试 vs 链路重连）。把它们打包成 5 层抽象之后，软件工程师可以用 <code>fetch()</code> 调地球另一端的服务而不用懂光相位检测。但<strong>遇到性能问题、丢包混沌、协议升级时，分层就是要把每层都拆开来看</strong>——这一部分就是干这件事。</p><h2 id="这一部分的章节" tabindex="-1">这一部分的章节 <a class="header-anchor" href="#这一部分的章节" aria-label="Permalink to &quot;这一部分的章节&quot;">​</a></h2><ul><li><a href="./phy/">物理层 / 数据链路层</a> — 以太网帧、CSMA/CD、PHY/MAC 分层、光纤、DWDM、机房布线</li><li><a href="./ip/">IP / 路由</a> — IPv4/v6、ICMP、ARP/NDP/DHCP、BGP/OSPF、NAT+conntrack</li><li><a href="./tcp/">TCP / UDP</a> — 三次握手四次挥手、TIME_WAIT、Reno/Cubic/BBR、SACK/RTO 估计</li><li><a href="./http/">HTTP / TLS</a> — 1.0→1.1→2→3 演进、TLS 1.3 握手与 0-RTT、证书链/PKI、gRPC/Protobuf</li><li><a href="./quic/">QUIC</a> — over UDP 解决什么、连接迁移、BBR 在 QUIC 下的特点</li></ul><p>读完你应该能回答这些问题，而不是只会说&quot;我学过计算机网络&quot;：</p><ol><li>为什么以太网帧最小是 <strong>64 字节</strong>而不是 32？为什么 1500 字节 MTU 沿用 40 年没人改？</li><li><strong>BGP vs OSPF</strong> 谁的收敛快？为什么 ISP 用 OSPF，跨 ISP 用 BGP？为什么 BGP 默认 30s 抑制？</li><li><strong>TCP Cubic vs BBR</strong> 在卫星链路、5G 移动网络、跨洋数据中心里各自赢谁？</li><li><strong>TLS 1.3 0-RTT</strong> 怎么保证保密性同时还能被 replay attack？应用层应该做什么限制？</li><li><strong>QUIC</strong> 为什么比 TCP+TLS 1.3 快？连接迁移到底解决了什么真问题？</li><li>为什么 <code>tcp_tw_recycle</code> 在 Linux 4.12 后被移除？为什么 NAT 后多 client 共用 IP 时它会丢包？</li><li>Google BBR v1 在 2016 部署后，2019 又换了 v2，到底什么场景下 v1 不公平？</li></ol><h2 id="这一部分的工程立场" tabindex="-1">这一部分的工程立场 <a class="header-anchor" href="#这一部分的工程立场" aria-label="Permalink to &quot;这一部分的工程立场&quot;">​</a></h2><p>每次给一个新协议栈调优，标配工具链：<code>tcpdump -i any -nn -X port 443 | wireshark -k -i -</code> 抓包看 header；<code>ss -tin</code> 看内核 socket 状态、cwnd、rtt；<code>iperf3</code> 测带宽；<code>ss -ian</code> 看中断分布；<code>ethtool -S eth0</code> 看 NIC 计数器（rx_missed / rx_no_dma_resources / alloc_rx_page_failed 都是热指标）；<code>bpftool prog show</code> 看 XDP；<code>perf top -e eth0:tx-qos-mismatch</code> 看软中断热路径。</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>这一部分凡是讲数字的地方（如 &quot;100G 显卡 1W 功耗&quot;、&quot;DWDM 单纤 80λ × 100G = 8Tbps&quot;、&quot;BBR ProbeBW 8 阶段 cycle 8s&quot;）都是公开论文/产品 datasheet 的实际值，不是随手编的。这些数字记下来，做架构决策时可以少打很多白板。</p></div>`,14)])])}const P=s(o,[["render",i]]);export{d as __pageData,P as default};
